#include <stack>
#include <vector>
#include <algorithm>

void demonstrate_adapter_restriction() {
    std::stack<int, std::vector<int>> s;
    s.push(10);

    // Error: stack does not provide iterators (begin/end)
    // std::sort(s.begin(), s.end()); 

    // Correct access enforces LIFO
    s.pop(); 
}
